var sm = get_node('/root/SettingsManager')
var fog = get_tree().get_first_node_in_group('fog_event')
var day = get_tree().get_first_node_in_group('day_cycle')
var player = get_tree().get_first_node_in_group('player')
var lantern = get_tree().get_first_node_in_group('lantern')
var stats_n = get_tree().get_first_node_in_group('player_stats')
var cam = get_viewport().get_camera_2d()
sm.set_menu_pause(false)
sm._paused_by_focus = false
get_tree().paused = false
lantern.apply_level(1, false)
fog.debug_jump_to_fog_night(7)
day.set_day_and_time(7, 0.76)
player.global_position = lantern.global_position + Vector2(22.0 * 16.0, 0.0)
stats_n.set_health(100.0)
if cam and cam.has_method('set_zoom_out'):
	cam.set_zoom_out(1.75)
return {'fog': fog.state, 'r': lantern.get_safe_radius_tiles(), 'dx': 22.0, 'safe': fog.is_position_safe(player.global_position)}
